css:
body {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    background-color: #121212;
    margin: 0;
}

#calculator {
    font-family: Arial, Helvetica, sans-serif;
    background-color: #1C1C1C;
    padding: 2vh 2vw;
    width: 90vw;
    max-width: 400px;
    border-radius: 10px;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.5);
    display: flex;
    flex-direction: column;
    align-items: center;
}

#display {
    background-color: #1C1C1C;
    color: white;
    text-align: right;
    font-size: 2rem;
    border: none;
    outline: none;
    width: 100%;
    height: 12vh;
    box-sizing: border-box;
    padding: 1vh;
}

#buttons {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1vw;
    padding: 2vh 0;
    width: 100%;
}

#buttons button {
    background-color: #505050;
    color: white;
    font-size: 1.8rem;
    text-align: center;
    width: 100%;
    height: 12vh;
    border-radius: 50px;
    border: none;
    transition: 0.2s;
    display: flex;
    justify-content: center;
    align-items: center;
}

#buttons button:hover {
    opacity: 0.7;
}

#buttons button:active {
    opacity: 0.9;
}

/* Special button styles */
#buttons button:nth-child(4n) { /* Right-side operators */
    background-color: #FF9500;
}

#buttons button:nth-child(-n+3) { /* Top row buttons */
    background-color: #D4D4D2;
    color: #1C1C1C;
}

/* Zero button spanning two columns */
#buttons button[value='0'] {
    grid-column: span 2;
    border-radius: 40px;
}

js:
const buttonValues = [
    "AC", "+/-", "%", "÷",
    "7", "8", "9", "×",
    "4", "5", "6", "-",
    "1", "2", "3", "+",
    "0", ".", "="
];
const rightSymbols = ["÷", "×", "-", "+", "="];
const topSymbols = ["AC", "+/-", "%"];

const display = document.getElementById("display");

//A+B, A×B, A-B, A÷B
let A = 0;
let operator = null;
let B = null;

function clearAll() {
    A = null;
    operator = null;
    B = null;
}

for (let i = 0; i < buttonValues.length; i++) {
    let value = buttonValues[i];
    let button = document.createElement("button");
    button.innerText = value;

    //styling button colors
    if (value == "0") {
        button.style.width = "180px";
        button.style.gridColumn = "span 2"; //take up 2 columns
    }
    else if (rightSymbols.includes(value)) {
        button.style.backgroundColor = "#FF9500";
    }
    else if (topSymbols.includes(value)) {
        button.style.backgroundColor = "#D4D4D2";
        button.style.color = "#1C1C1C";
    }

    //process button clicks
    button.addEventListener("click", function () {
        if (rightSymbols.includes(value)) {
            if (value == "=") {
                if (A != null) {
                    B = display.value;
                    let numA = Number(A);
                    let numB = Number(B);

                    if (operator == "÷") {
                        display.value = numA / numB;
                    }
                    else if (operator == "×") {
                        display.value = numA * numB;
                    }
                    else if (operator == "-") {
                        display.value = numA - numB;
                    }
                    else if (operator == "+") {
                        display.value = numA + numB;
                    }
                    clearAll();
                }
            }
            else {
                operator = value; //÷ × - +
                A = display.value;
                display.value = "";
            }
        }
        else if (topSymbols.includes(value)) { //AC +/- %
            if (value == "AC") {
                clearAll();
                display.value = "";
            }
            else if (value == "+/-") {
                if (display.value != "" && display.value != "0") {
                    if (display.value[0] == "-") { //remove -
                        display.value = display.value.slice(1);
                    } else { //add -
                        display.value = "-" + display.value;
                    }
                }
            }
            else if (value == "%") {
                display.value = Number(display.value) / 100;
            }
        }
        else { //digits or .
            if (value == ".") {
                //don't add multiple decimal places
                if (display.value != "" && !display.value.includes(value)) {
                    display.value += value;
                }
            }
            //not a dot, number instead
            else if (display.value == "0") {
                display.value = value;
            }
            else {
                display.value += value;
            }
        }
    });

    //add button to calculator
    document.getElementById("buttons").appendChild(button);
}
